ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
---
soapenv#Envelope @("xmlns:tem": tem, "xmlns:tier": tier, "xmlns:ws": ws): {
    soapenv#Header: {},
    soapenv#Body: {
        'tem:RespuestaTransaccion': {
            'tem:WSRequestHeader': {
                'tier:system': {
                    'tier:correlationId': correlationId,
                    'tier:name': vars.name,
                    'tier:processingServer': p('generic-notifier.fact')
                }
            },
            'tem:WSRequestBody': {
            	'ws:Descripcion': write(payload, 'application/json'),
            	'ws:Fecha': vars.map.fechaInicioFacturacion,
            	'ws:IdServicio': vars.map.idServicio,
            	'ws:NumeroOC': vars.map.numeroOC,
                'ws:OrdenOM': vars.map.ordenOM,
                'ws:Resultado': if (vars.resultado == '0') p('generic-notifier.successCode') else p('generic-notifier.errorCode'),
                'ws:TipoTransaccion': p('generic-notifier.facturacion')
            }
        }
    }
}
